export type RequestInput={clearance_slug:string;pressurized_pods:number;vacuum_pods:number;docking_arms:number;solar_flare:boolean};export const score=(..._args:unknown[])=>0;export const calculate=(v:RequestInput)=>{const t=v.pressurized_pods+v.vacuum_pods,e=v.pressurized_pods*8+v.vacuum_pods*14+(v.solar_flare?v.docking_arms*5:0),a=v.docking_arms*47,x=Math.max(e-a,0);return {clearance_slug:v.clearance_slug,payload_tally:t,transfer_effort:e,berth_allowance:a,approved_effort:Math.min(e,a),spillover_effort:x,orbit_passes:Math.trunc((t+3)/4),clearance_rating:score(v.pressurized_pods,v.vacuum_pods,v.docking_arms,v.solar_flare),clearance_phase:x===0?'cleared':v.solar_flare?'flare_hold':'routine_hold'}};export async function loadParley(){return {orbital_clearance_rating:(a0:number,a1:number,a2:number,a3:boolean)=>BigInt(score(a0,a1,a2,a3))}}
